# Calculate the number of independent sets in a path graph P_n, which is F_{n+2}.
# We need A_21 = F_{23}.
def fibonacci(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

# A_n = F_{n+2}
n = 21
result = fibonacci(n + 2)
print(f"A_{n} = F_{n+2} = {result}")
